#include "nudl/interpreter.hpp"
#include <cmath>
#include <iostream>
#include <sstream>
#include <stdexcept>
namespace nudl {
Interpreter::Interpreter(const Program& p):program_(p){}
double Interpreter::number(const RuntimeValue&v){if(auto p=std::get_if<double>(&v.data))return *p;if(auto p=std::get_if<bool>(&v.data))return *p?1.0:0.0;throw std::runtime_error("expected numeric value");}
bool Interpreter::truthy(const RuntimeValue&v)const{if(std::holds_alternative<std::monostate>(v.data))return false;if(auto p=std::get_if<bool>(&v.data))return *p;if(auto p=std::get_if<double>(&v.data))return *p!=0.0;if(auto p=std::get_if<std::string>(&v.data))return !p->empty();return true;}
RuntimeValue Interpreter::eval(const Expr&e){return std::visit([&](auto const&x)->RuntimeValue{using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,Literal>){if(x.kind==Literal::Kind::Number)return RuntimeValue{std::stod(x.value)};if(x.kind==Literal::Kind::Boolean)return RuntimeValue{x.value=="true"};if(x.kind==Literal::Kind::String)return RuntimeValue{x.value};return RuntimeValue{std::monostate{}};}else if constexpr(std::is_same_v<T,Name>){auto i=globals_.find(x.value);if(i==globals_.end())throw std::runtime_error("undefined name: "+x.value);return i->second;}else if constexpr(std::is_same_v<T,Unary>){auto v=eval(*x.rhs);if(x.op=="-")return RuntimeValue{-number(v)};if(x.op=="!")return RuntimeValue{!truthy(v)};return RuntimeValue{std::monostate{}};}else if constexpr(std::is_same_v<T,Binary>){return eval_binary(x);}else if constexpr(std::is_same_v<T,Call>){return eval_call(x);}else{auto a=std::make_shared<RuntimeArray>();for(auto const&e:x.elements)a->push_back(eval(*e));return RuntimeValue{a};}},e.node);}
RuntimeValue Interpreter::eval_binary(const Binary&b){auto l=eval(*b.lhs),r=eval(*b.rhs);if(b.op=="+"){if(auto ls=std::get_if<std::string>(&l.data))if(auto rs=std::get_if<std::string>(&r.data))return RuntimeValue{*ls+*rs};return RuntimeValue{number(l)+number(r)};}if(b.op=="-")return RuntimeValue{number(l)-number(r)};if(b.op=="*")return RuntimeValue{number(l)*number(r)};if(b.op=="/")return RuntimeValue{number(l)/number(r)};if(b.op=="%")return RuntimeValue{std::fmod(number(l),number(r))};if(b.op=="==")return RuntimeValue{runtime_value_to_string(l)==runtime_value_to_string(r)};if(b.op=="!=")return RuntimeValue{runtime_value_to_string(l)!=runtime_value_to_string(r)};if(b.op=="<")return RuntimeValue{number(l)<number(r)};if(b.op=="<=")return RuntimeValue{number(l)<=number(r)};if(b.op==">")return RuntimeValue{number(l)>number(r)};if(b.op==">=")return RuntimeValue{number(l)>=number(r)};throw std::runtime_error("unknown operator: "+b.op);}
const Function* Interpreter::find_function(const std::string&n)const{for(auto const&f:program_.functions)if(f.name==n)return &f;return nullptr;}
RuntimeValue Interpreter::eval_call(const Call&c){if(c.callee=="print"){for(auto const&a:c.args)std::cout<<runtime_value_to_string(eval(*a))<<"\n";return RuntimeValue{std::monostate{}};}auto f=find_function(c.callee);if(!f)throw std::runtime_error("unknown function: "+c.callee);if(f->params.size()!=c.args.size())throw std::runtime_error("wrong argument count for "+c.callee);auto saved=globals_;for(size_t i=0;i<f->params.size();++i)globals_[f->params[i].name]=eval(*c.args[i]);RuntimeValue result{std::monostate{}};bool returned=false;for(auto const&s:f->body){exec(*s,result,returned);if(returned)break;}globals_=std::move(saved);return result;}
void Interpreter::exec(const Stmt&s,RuntimeValue&result,bool&returned){std::visit([&](auto const&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,Binding>)globals_[x.name]=eval(*x.value);else if constexpr(std::is_same_v<T,ExprStmt>)eval(*x.value);else if constexpr(std::is_same_v<T,Return>){result=eval(*x.value);returned=true;}else if constexpr(std::is_same_v<T,If>){auto&b=truthy(eval(*x.condition))?x.then_branch:x.else_branch;for(auto const&s:b){exec(*s,result,returned);if(returned)break;}}else if constexpr(std::is_same_v<T,While>){while(truthy(eval(*x.condition))&&!returned)for(auto const&s:x.body){exec(*s,result,returned);if(returned)break;}}},s.node);}
RuntimeValue Interpreter::run(){RuntimeValue result{std::monostate{}};bool returned=false;for(auto const&s:program_.statements){exec(*s,result,returned);if(returned)break;}if(find_function("main")){Call c{"main",{}};return eval_call(c);}return result;}
std::string runtime_value_to_string(const RuntimeValue&v){return std::visit([](auto const&x)->std::string{using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,std::monostate>)return"null";else if constexpr(std::is_same_v<T,bool>)return x?"true":"false";else if constexpr(std::is_same_v<T,std::string>)return x;else if constexpr(std::is_same_v<T,double>){std::ostringstream s;s<<x;return s.str();}else return"[array]";},v.data);}
}